<script setup lang="ts">
definePageMeta({ layout: 'admin', middleware: 'admin' })

const { data, refresh } = await useFetch<{ products: any[]; categories: string[] }>('/api/admin/products')
const products = computed(() => data.value?.products || [])
const categories = computed(() => data.value?.categories || [])
const search = ref('')
const statusFilter = ref('TODOS')
const categoryFilter = ref('TODAS')
const editingId = ref('')
const deleteTarget = ref<any | null>(null)
const selectedFiles = ref<File[]>([])
const previews = ref<string[]>([])
const existingImages = ref<string[]>([])
const saving = ref(false)
const uploading = ref(false)
const message = ref('')
const formError = ref('')
const form = reactive({ name: '', sku: '', slug: '', shortDescription: '', description: '', category: 'General', price: '', previousPrice: '', cost: '', stock: '', weight: '', dimensions: '', features: '', metaTitle: '', metaDescription: '', status: 'ACTIVO', externalProvider: '', externalProductId: '', externalProductUrl: '', externalAutoPublish: false, conversionActivity: null as boolean | null, conversionActiveViewers: null as boolean | null, conversionVisits: null as boolean | null, conversionOrders: null as boolean | null, conversionOffer: null as boolean | null, conversionStockAlert: null as boolean | null, conversionAvailabilityBar: null as boolean | null, conversionTrust: null as boolean | null, offerStartAt: '', offerEndAt: '', promotionalPrice: '' })

const filteredProducts = computed(() => products.value.filter(product => (categoryFilter.value === 'TODAS' || product.category === categoryFilter.value) && (statusFilter.value === 'TODOS' || (statusFilter.value === 'ELIMINADOS' ? product.status === 'ELIMINADO' : product.status === statusFilter.value)) && `${product.name} ${product.sku || ''}`.toLowerCase().includes(search.value.toLowerCase())))
const money = (value: number) => new Intl.NumberFormat('es-CO', { style: 'currency', currency: 'COP', maximumFractionDigits: 0 }).format(value)
const statusLabel = (status: string) => status === 'ELIMINADO' ? 'Eliminado' : status === 'ACTIVO' ? 'Activo' : 'Inactivo'

const selectImages = (event: Event) => {
  const input = event.target as HTMLInputElement
  const files = Array.from(input.files || []).filter(file => file.type.startsWith('image/'))
  selectedFiles.value = [...selectedFiles.value, ...files]
  previews.value = [...previews.value, ...files.map(file => URL.createObjectURL(file))]
}
const dropImages = (event: DragEvent) => { const files = Array.from(event.dataTransfer?.files || []).filter(file => file.type.startsWith('image/')); selectedFiles.value = [...selectedFiles.value, ...files]; previews.value = [...previews.value, ...files.map(file => URL.createObjectURL(file))] }
const removeNewImage = (index: number) => { selectedFiles.value.splice(index, 1); URL.revokeObjectURL(previews.value[index]); previews.value.splice(index, 1) }
const removeExistingImage = (index: number) => { existingImages.value.splice(index, 1) }
const makePrimary = (images: string[], index: number) => { const [image] = images.splice(index, 1); images.unshift(image) }
const uploadImages = async () => {
  const urls: string[] = []
  for (const file of selectedFiles.value) { const body = new FormData(); body.append('image', file); const result = await $fetch<{ url: string }>('/api/admin/products/upload', { method: 'POST', body }); urls.push(result.url) }
  return urls
}
const clearForm = () => { editingId.value = ''; existingImages.value = []; selectedFiles.value = []; previews.value.forEach(url => URL.revokeObjectURL(url)); previews.value = []; Object.assign(form, { name: '', sku: '', slug: '', shortDescription: '', description: '', category: categories.value[0] || 'General', price: '', previousPrice: '', cost: '', stock: '', weight: '', dimensions: '', features: '', metaTitle: '', metaDescription: '', status: 'ACTIVO', externalProvider: '', externalProductId: '', externalProductUrl: '', externalAutoPublish: false, conversionActivity: null, conversionActiveViewers: null, conversionVisits: null, conversionOrders: null, conversionOffer: null, conversionStockAlert: null, conversionAvailabilityBar: null, conversionTrust: null, offerStartAt: '', offerEndAt: '', promotionalPrice: '' }); formError.value = '' }
const editProduct = (product: any) => { editingId.value = product._id; existingImages.value = [...(product.images || [])]; Object.assign(form, { name: product.name || '', sku: product.sku || '', slug: product.slug || '', shortDescription: product.shortDescription || '', description: product.description || '', category: product.category || 'General', price: product.price, previousPrice: product.previousPrice ?? '', cost: product.cost ?? '', stock: product.stock, weight: product.weight || '', dimensions: product.dimensions || '', features: (product.features || []).join(', '), metaTitle: product.metaTitle || '', metaDescription: product.metaDescription || '', status: product.status || 'ACTIVO', externalProvider: product.externalReviews?.provider || '', externalProductId: product.externalReviews?.productId || '', externalProductUrl: product.externalReviews?.productUrl || '', externalAutoPublish: Boolean(product.externalReviews?.autoPublish), conversionActivity: product.conversion?.activity ?? null, conversionActiveViewers: product.conversion?.activeViewers ?? null, conversionVisits: product.conversion?.visits ?? null, conversionOrders: product.conversion?.orders ?? null, conversionOffer: product.conversion?.offer ?? null, conversionStockAlert: product.conversion?.stockAlert ?? null, conversionAvailabilityBar: product.conversion?.availabilityBar ?? null, conversionTrust: product.conversion?.trust ?? null, offerStartAt: product.conversion?.offerStartAt || '', offerEndAt: product.conversion?.offerEndAt || '', promotionalPrice: product.conversion?.promotionalPrice ?? '' }); formError.value = ''; window.scrollTo({ top: 0, behavior: 'smooth' }) }
const validateForm = () => { if (!form.name.trim()) return 'El nombre del producto es obligatorio.'; if (!Number.isFinite(Number(form.price)) || Number(form.price) <= 0) return 'El precio debe ser mayor que 0.'; if (!Number.isInteger(Number(form.stock)) || Number(form.stock) < 0) return 'El stock no puede ser negativo.'; return '' }
const saveProduct = async () => {
  formError.value = validateForm(); if (formError.value) return
  saving.value = true; uploading.value = selectedFiles.value.length > 0; message.value = ''
  try {
    const uploaded = await uploadImages(); const images = [...existingImages.value, ...uploaded]; const payload = { ...form, price: Number(form.price), previousPrice: form.previousPrice === '' ? null : Number(form.previousPrice), cost: form.cost === '' ? null : Number(form.cost), stock: Number(form.stock), images, features: form.features.split(',').map(value => value.trim()).filter(Boolean), externalReviews: { provider: form.externalProvider, productId: form.externalProductId, productUrl: form.externalProductUrl, autoPublish: form.externalAutoPublish }, conversion: { activity: form.conversionActivity, activeViewers: form.conversionActiveViewers, visits: form.conversionVisits, orders: form.conversionOrders, offer: form.conversionOffer, stockAlert: form.conversionStockAlert, availabilityBar: form.conversionAvailabilityBar, trust: form.conversionTrust, offerStartAt: form.offerStartAt, offerEndAt: form.offerEndAt, promotionalPrice: form.promotionalPrice } }
    await $fetch(editingId.value ? `/api/admin/products/${editingId.value}` : '/api/admin/products', { method: editingId.value ? 'PATCH' : 'POST', body: payload })
    const wasEditing = Boolean(editingId.value); clearForm(); message.value = wasEditing ? 'Producto actualizado correctamente.' : 'Producto creado correctamente.'; await refresh()
  } catch (error: any) { formError.value = error?.data?.message || 'No fue posible actualizar el producto. Inténtalo nuevamente.' } finally { saving.value = false; uploading.value = false }
}
const toggleStatus = async (product: any) => { try { await $fetch(`/api/admin/products/${product._id}/status`, { method: 'PATCH', body: { status: product.status === 'ACTIVO' ? 'INACTIVO' : 'ACTIVO' } }); message.value = product.status === 'ACTIVO' ? 'Producto desactivado.' : 'Producto activado.'; await refresh() } catch (error: any) { message.value = error?.data?.message || 'No fue posible cambiar el estado.' } }
const syncExternalReviews = async () => { if (!editingId.value) return; saving.value = true; try { const result = await $fetch<{ count: number }>(`/api/admin/products/${editingId.value}/reviews/sync`, { method: 'POST' }); message.value = `${result.count} reseñas externas sincronizadas correctamente.`; await refresh() } catch (error: any) { message.value = error?.data?.message || 'La sincronización no está disponible. Las reseñas anteriores se conservaron.' } finally { saving.value = false } }
const confirmDelete = async () => { if (!deleteTarget.value) return; try { const result = await $fetch<{ mode: string; message?: string }>(`/api/admin/products/${deleteTarget.value._id}`, { method: 'DELETE' }); message.value = result.mode === 'soft' ? result.message || 'Producto desactivado para conservar pedidos históricos.' : 'Producto eliminado correctamente.'; if (editingId.value === deleteTarget.value._id) clearForm(); deleteTarget.value = null; await refresh() } catch (error: any) { message.value = error?.data?.message || 'No fue posible eliminar el producto.'; deleteTarget.value = null } }
</script>

<template>
  <div class="admin-page product-management-page">
    <div class="admin-page-heading"><div><p class="eyebrow">CATÁLOGO</p><h1>Productos</h1><p>Busca, actualiza y controla la disponibilidad de tu catálogo.</p></div><button type="button" class="button dashboard-primary" @click="clearForm">+ Nuevo producto</button></div>
    <div class="product-management-toolbar"><label class="product-search"><span>⌕</span><input v-model="search" type="search" placeholder="Buscar por nombre o SKU" aria-label="Buscar productos"></label><select v-model="statusFilter" aria-label="Filtrar por estado"><option value="TODOS">Todos los estados</option><option value="ACTIVO">Activos</option><option value="INACTIVO">Inactivos</option><option value="ELIMINADOS">Eliminados</option></select><select v-model="categoryFilter" aria-label="Filtrar por categoría"><option value="TODAS">Todas las categorías</option><option v-for="category in categories" :key="category" :value="category">{{ category }}</option></select><span class="product-result-count">{{ filteredProducts.length }} productos</span></div>
    <p v-if="message" class="form-success product-page-message">{{ message }}</p>
    <div class="publication-layout product-admin-layout product-management-layout">
      <form class="admin-form-card product-create-card product-edit-form" @submit.prevent="saveProduct">
        <div class="card-heading"><div><span class="card-kicker">{{ editingId ? 'EDICIÓN' : 'CATÁLOGO' }}</span><h2>{{ editingId ? 'Editar producto' : 'Nuevo producto' }}</h2></div><button v-if="editingId" type="button" class="form-cancel-link" @click="clearForm">Cancelar</button></div>
         <fieldset><legend>Información del producto</legend><label>Nombre del producto <b>*</b><input v-model="form.name" required placeholder="Ej. Lámpara LED portátil"></label><div class="form-row"><label>Código del producto<input v-model="form.sku" placeholder="Se genera si queda vacío"></label><label>Slug<input v-model="form.slug" placeholder="url-del-producto"></label></div><label>Descripción corta<input v-model="form.shortDescription" maxlength="240" placeholder="Resumen breve del producto"></label><label>Descripción completa<textarea v-model="form.description" rows="4" placeholder="Describe el producto..."></textarea></label><label>Categoría<select v-model="form.category"><option value="General">General</option><option v-for="category in categories" :key="category" :value="category">{{ category }}</option><option v-if="form.category && form.category !== 'General' && !categories.includes(form.category)" :value="form.category">{{ form.category }}</option></select></label></fieldset>
         <fieldset><legend>Precios e inventario</legend><div class="form-row"><label>Precio de venta <b>*</b><input v-model="form.price" type="number" min="1" required placeholder="0"></label><label>Precio anterior<input v-model="form.previousPrice" type="number" min="0" placeholder="Opcional"></label></div><div class="form-row"><label>Costo interno<input v-model="form.cost" type="number" min="0" placeholder="Opcional"></label><label>Disponibles <b>*</b><input v-model="form.stock" type="number" min="0" step="1" required placeholder="0"></label></div><label>Estado<select v-model="form.status"><option value="ACTIVO">Activo</option><option value="INACTIVO">Inactivo</option><option v-if="editingId && form.status === 'ELIMINADO'" value="ELIMINADO">Eliminado</option></select></label></fieldset>
         <fieldset><legend>Galería del producto</legend><label class="product-dropzone" @dragover.prevent @drop.prevent="dropImages"><input type="file" accept="image/*" multiple @change="selectImages"><span class="upload-cloud-icon">↥</span><strong>Agregar imágenes</strong><small>Cloudinary · agrega las que necesites</small><span class="upload-select-label">Elegir imágenes o arrastrarlas</span></label><div v-if="existingImages.length || previews.length" class="product-previews product-edit-previews"><div v-for="(image, index) in existingImages" :key="image" class="product-preview"><img :src="image" alt="Imagen del producto"><button type="button" aria-label="Eliminar imagen" @click="removeExistingImage(index)">×</button><span v-if="index === 0">Principal</span><button v-if="index > 0" type="button" class="make-primary" @click="makePrimary(existingImages, index)">Principal</button></div><div v-for="(preview, index) in previews" :key="preview" class="product-preview"><img :src="preview" alt="Nueva imagen"><button type="button" aria-label="Quitar imagen" @click="removeNewImage(index)">×</button></div></div></fieldset>
           <fieldset><legend>Características y SEO</legend><label>Características <small>(separadas por comas)</small><input v-model="form.features" placeholder="Ligero, Resistente, Garantía"></label><div class="form-row"><label>Peso<input v-model="form.weight" placeholder="Ej. 500 g"></label><label>Dimensiones<input v-model="form.dimensions" placeholder="Ej. 20 × 10 × 5 cm"></label></div><label>Meta title<input v-model="form.metaTitle" maxlength="160"></label><label>Meta description<textarea v-model="form.metaDescription" rows="2" maxlength="300"></textarea></label></fieldset><fieldset><legend>Reseñas externas</legend><label>Fuente<select v-model="form.externalProvider"><option value="">Ninguna</option><option value="ALIEXPRESS">AliExpress</option></select></label><label>Identificador del producto externo<input v-model="form.externalProductId" placeholder="ID entregado por el proveedor"></label><label>URL del producto externo<input v-model="form.externalProductUrl" type="url" placeholder="https://..."></label><label class="toggle-label"><span><strong>Publicar automáticamente</strong><small>Solo si las condiciones del proveedor lo permiten.</small></span><input v-model="form.externalAutoPublish" type="checkbox" class="toggle-input"><i class="toggle-track"></i></label><div v-if="editingId && form.externalProvider" class="external-sync-note"><p>Sincroniza las últimas reseñas guardadas. Las existentes se conservan si el proveedor falla.</p><button type="button" class="button is-light" @click="syncExternalReviews">Sincronizar reseñas</button></div></fieldset><fieldset><legend>Conversión visual</legend><p class="field-help">Deja en automático las opciones que deben heredar la configuración global.</p><div class="conversion-product-grid"><label>Actividad<select v-model="form.conversionActivity"><option :value="null">Global</option><option :value="true">Activa</option><option :value="false">Inactiva</option></select></label><label>Personas viendo<select v-model="form.conversionActiveViewers"><option :value="null">Global</option><option :value="true">Activa</option><option :value="false">Inactiva</option></select></label><label>Visitas<select v-model="form.conversionVisits"><option :value="null">Global</option><option :value="true">Activa</option><option :value="false">Inactiva</option></select></label><label>Pedidos<select v-model="form.conversionOrders"><option :value="null">Global</option><option :value="true">Activa</option><option :value="false">Inactiva</option></select></label><label>Alertas de disponibles<select v-model="form.conversionStockAlert"><option :value="null">Global</option><option :value="true">Activa</option><option :value="false">Inactiva</option></select></label><label>Barra de disponibilidad<select v-model="form.conversionAvailabilityBar"><option :value="null">Global</option><option :value="true">Activa</option><option :value="false">Inactiva</option></select></label><label>Mensajes de confianza<select v-model="form.conversionTrust"><option :value="null">Global</option><option :value="true">Activa</option><option :value="false">Inactiva</option></select></label><label>Oferta con fecha<select v-model="form.conversionOffer"><option :value="null">Global</option><option :value="true">Activa</option><option :value="false">Inactiva</option></select></label></div><div class="form-row"><label>Precio promocional<input v-model="form.promotionalPrice" type="number" min="0"></label><label>Inicio de oferta<input v-model="form.offerStartAt" type="datetime-local"></label></div><label>Fin de oferta<input v-model="form.offerEndAt" type="datetime-local"></label></fieldset>
        <p v-if="formError" class="form-error">{{ formError }}</p><div class="product-form-actions"><button class="button publication-save" :disabled="saving || uploading">{{ uploading ? 'Subiendo imágenes...' : saving ? 'Guardando...' : editingId ? 'Guardar cambios' : 'Crear producto' }} <span>↗</span></button><button v-if="editingId" type="button" class="button is-light" @click="clearForm">Cancelar</button></div>
      </form>
      <section class="admin-form-card product-list-card product-list-management"><div class="card-heading"><div><span class="card-kicker">INVENTARIO</span><h2>Catálogo actual</h2></div><span class="content-count">{{ filteredProducts.length }}</span></div><div v-if="!filteredProducts.length" class="recent-empty"><span>✦</span><p>No hay productos con estos filtros.</p><small>Prueba otra búsqueda o crea un producto nuevo.</small></div><div class="product-table-wrap" v-else><table class="admin-table product-table"><thead><tr><th>Producto</th><th>Categoría</th><th>Precio</th><th>Stock</th><th>Estado</th><th>Creado</th><th>Acciones</th></tr></thead><tbody><tr v-for="product in filteredProducts" :key="product._id"><td><div class="product-list-name"><img :src="product.images?.[0] || '/Logo/logotip.jpg'" :alt="product.name"><div><strong>{{ product.name }}</strong><small>{{ product.sku || 'Sin SKU' }}</small></div></div></td><td>{{ product.category || 'General' }}</td><td><strong>{{ money(product.price) }}</strong><del v-if="product.previousPrice">{{ money(product.previousPrice) }}</del></td><td>{{ product.stock }}</td><td><span class="product-status" :class="`product-status-${product.status.toLowerCase()}`">{{ statusLabel(product.status) }}</span></td><td>{{ new Date(product.createdAt).toLocaleDateString('es-CO') }}</td><td><div class="product-actions"><button type="button" class="table-action" @click="editProduct(product)">Editar</button><button v-if="product.status !== 'ELIMINADO'" type="button" class="table-action" @click="toggleStatus(product)">{{ product.status === 'ACTIVO' ? 'Desactivar' : 'Activar' }}</button><button type="button" class="table-action product-delete-action" @click="deleteTarget = product">Eliminar</button></div></td></tr></tbody></table><div class="product-mobile-list"><article v-for="product in filteredProducts" :key="`mobile-${product._id}`" class="product-mobile-card"><div class="product-mobile-heading"><img :src="product.images?.[0] || '/Logo/logotip.jpg'" :alt="product.name"><div><strong>{{ product.name }}</strong><small>{{ product.sku || 'Sin SKU' }}</small></div><span class="product-status" :class="`product-status-${product.status.toLowerCase()}`">{{ statusLabel(product.status) }}</span></div><div class="product-mobile-data"><span><small>Precio</small>{{ money(product.price) }}</span><span><small>Stock</small>{{ product.stock }}</span><span><small>Categoría</small>{{ product.category || 'General' }}</span></div><div class="product-actions"><button type="button" class="table-action" @click="editProduct(product)">Editar</button><button v-if="product.status !== 'ELIMINADO'" type="button" class="table-action" @click="toggleStatus(product)">{{ product.status === 'ACTIVO' ? 'Desactivar' : 'Activar' }}</button><button type="button" class="table-action product-delete-action" @click="deleteTarget = product">Eliminar</button></div></article></div></div></section>
    </div>
    <div v-if="deleteTarget" class="admin-modal-backdrop" @click.self="deleteTarget = null"><section class="admin-modal" role="dialog" aria-modal="true" aria-labelledby="delete-product-title"><h2 id="delete-product-title">¿Eliminar producto?</h2><p>Estás a punto de eliminar <strong>{{ deleteTarget.name }}</strong>. Si tiene pedidos históricos, se conservará de forma segura como inactivo.</p><div class="admin-modal-actions"><button type="button" class="button is-light" @click="deleteTarget = null">Cancelar</button><button type="button" class="button product-delete-button" @click="confirmDelete">Eliminar producto</button></div></section></div>
  </div>
</template>
